            ['section' => 'Comprehension', 'type' => 'mcq', 'question_text' => 'Why did Ryder carry off the wrong goose?', 'option_a' => 'Two barred-tailed birds stood in the yard and nobody could tell them apart', 'option_b' => 'His sister sold the right bird before he returned', 'option_c' => 'The goose with the stone flew away over the sheds', 'option_d' => 'Peterson had already bought the bird that morning', 'correct_option' => 'a'],
