            ['section' => 'Comprehension', 'type' => 'matching', 'question_text' => 'Match each figure to their part.', 'match_pairs' => [['left' => 'Valentin', 'right' => 'Chief of the Paris police who follows the unreasonable in darkness'], ['left' => 'Flambeau', 'right' => 'Colossus of crime disguised as a second priest'], ['left' => 'Father Brown', 'right' => 'Small priest who suspects early and turns every trick around'], ['left' => 'The sweetshop woman', 'right' => 'Shopkeeper who posted off the parcel Father Brown never owned']]],
