            ['section' => 'Comprehension', 'type' => 'matching', 'question_text' => 'Match each figure to their part.', 'match_pairs' => [['left' => 'Pierre Aronnax', 'right' => 'Paris professor who tells the tale of the voyage under the seas'], ['left' => 'Ned Land', 'right' => 'Canadian harpooner whose quick throw saves the captain from a shark'], ['left' => 'Conseil', 'right' => 'Faithful servant who can classify every beast but recall few names'], ['left' => 'Captain Nemo', 'right' => 'Commander of the Nautilus at war with the world above']]],
            ['section' => 'Comprehension', 'type' => 'mcq', 'question_text' => 'How did those aboard survive five days sealed under the ice?', 'option_a' => 'Boiling water from the boilers melted a trench until the last pane cracked open', 'option_b' => 'They drilled upward with pickaxes alone day and night', 'option_c' => 'The Nautilus rammed her way out through the thickest wall', 'option_d' => 'Fresh air came through a crack left above the ice shelf', 'correct_option' => 'a'],
