            ['section' => 'Comprehension', 'type' => 'matching', 'question_text' => 'Match each figure to their part.', 'match_pairs' => [['left' => 'Lobo', 'right' => 'Giant gray king of the Currumpaw who outwitted men for years'], ['left' => 'Blanca', 'right' => 'White she-wolf whose death broke the heart of her mate'], ['left' => 'Tannerey', 'right' => 'Texan hunter whose best horse died in the losing chase'], ['left' => 'The narrator', 'right' => 'Old wolf hunter asked by a ranching friend to try his hand']]],
